def solve(nums_, k):
    """Return the k'th smallest value in nums_."""
    n = len(nums_)

    if n == 1:
        return nums_[0]

    if k == 1:
        return min(nums_)

    if k == n:
        return max(nums_)

    median_index = (n - 1) // 2
    pivot = nums_[median_index]
    left = [x for x in nums_ if x < pivot]
    right = [x for x in nums_ if x > pivot]
    middle = [x for x in nums_ if x == pivot]

    min_left = len(middle) + sum(len(list_1) for list_1 in (left + middle))
    max_right = n - len(middle) - sum(len(list_2) for list_2 in (middle + right))

    if k <= min_left:
        return solve(left, k)
    elif k <= max_right + len(middle):
        return pivot
    else:
        return solve(right, k - max_right - len(middle))

