from bisect import bisect_left

def solve(nums, k):
    nums = sorted(nums)

    # Find the value in array that is equal to nums[k-1] then return it.
    for i in range(len(nums)):
        if nums[i] == nums[k-1]:
            return nums[i]

    # Below here I have defined quick_select to find you k-th order statistic.

    def quick_select(array, key, left, right):
        if left == right:
            return array[left]

        i = bisect_left(array, key, left, right)
        if i < len(array) and array[i] == key:
            return array[i]

        pivot = array[left]
        pos = left
        i = 1
        if i > 0:
            k = key - array[left]
        else:
            k = pivot - array[pos]

        for j in range(left, right, i):
            if array[j] < pivot:
                array[j], array[pos] = array[pos], array[j]
                pos += 1
            i += 1

        array[pos], array[left] = array[left], array[pos]
        if pos - left + 1 < k:
            return quick_select(array, key, pos, right)
        elif pos - left + 1 > k:
            return quick_select(array, key, left, pos)
        else:
            return key

    # --- Solution ---

    return quick_select(nums, k, 0, len(nums)-1)
