def solve(n, edges):
    # Check input
    if n < 1 or n > 300:
        return None
    if len(edges) < 0 or len(edges) > 1500:
        return None
    if not all(0 <= u < n for u in edges) or not all(0 <= v < n for v in edges):
        return None
    if not all(edge[0] != edge[1] for edge in edges):
        return None

    # Initialize graph
    graph = {i: [] for i in range(n)}
    for edge in edges:
        # Note that we are using edge[i] to access the i-th element of edge
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])

    # Create DFS function
    def dfs(node):
        # Check if node has been visited
        if node not in visited:
            visited.append(node)
            # Visit all nodes connected to node
            for neighbor in graph[node]:
                dfs(neighbor)

    # Run DFS to find connected components
    dfs_components = set()
    dfs_stack = []
    for node in range(n):
        if node not in graph:
            continue
        dfs(node)
        dfs_components.add(len(dfs_stack))
        dfs_stack = [1 for num in range(n)]

    return len(dfs_components)
