  let goalX = goal[0].x;
  let goalY = goal[0].y;
  let visited = new Set();
  let queue = [{
    cell: start,
    direction: directions[0] // We start on "up"
  }];
  while (queue.length > 0) {
    let curPos = queue.shift();
    let curX = curPos.cell.x;
    let curY = curPos.cell.y;
    if (curX == goalX && curY == goalY) {
      queue.reverse();
      while (queue.length > 0) {
        visited.add(({ x: queue[0].cell.x, y: queue[0].cell.y }));
        result.push(({ x: queue[0].cell.x, y: queue[0].cell.y }));
        queue.shift();
      }
      result.push(({ x: goalX, y: goalY }));
      return result;
    }
    for (let i = 0; i < 2; i++) {
      let posX = curX + directions[i].x;
