using namespace std;

vector<int> topologicalSort(const vector<vector<int>>& dag, int start) {
    int numVertices = dag.size();
    vector<int> visited(numVertices, 0);
    vector<int> result;
    vector<int> lowLink(numVertices, 0);
    vector<int> parent(numVertices, 0);
    int step = start;
    visited[step] = 1;
    for (vector<int>& item : dag[start]) {
        parent[item] = step;
        if (!visited[item]) {
            lowLink[item] = step;
            result.push_back(item);
	        helper(dag, visited, lowLink, parent, item, result);
        }
    }
    return result;
}

void helper(const vector<vector<int>>& dag, vector<int>& visited,
             vector<int>& lowLink, vector<int>& parent, const int item,
             vector<int>& result) {
    visited[item] = 1;
    for (vector<int>& child : dag[item]) {
        if (!visited[child]) {
            parent[child] = item;
            lowLink[child] = step;
            if (lowLink[child] == 0) {
                step = lowLink[child];
                result.push_back(child);
            }
            helper(dag, visited, lowLink, parent, child, result);
            parent[item] = 0;
        }
        if (lowLink[child] <= parent[item]) {
            cout << "Can't sort!";
            return;
        }
    }
}

