two_max_freqs = hist.values()[:2]
discarded_idx = 0 not in two_max_freqs or two_max_freqs == two_max_freqs[1]
max_freq = max_freqs[1 if discarded_idx else 0]
if discarded_idx:
for n in hist:
if hist[n] == max_freq:
hist[n] = 0
# sort hist by frequency
sorted_hist = sorted(hist, key=hist.get)
# set k to the second highest frequency (discarding any duplicates)
k_th_val = sorted_hist[-k]
