function solve(n, edges):
    # Create an adjacency list representation of the graph
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Recursively explore the graph to find cycles using depth-first search
    def dfs(u, visited, parent):
        visited[u] = True
        for v in graph[u]:
            if v == parent:
                continue
            if not visited[v]:
                if dfs(v, visited, u):
                    return True
            else:
                if v != parent:
                    return True
        return False

    # Start the depth-first search from each node to find cycles
    for u in range(n):
        visited = [False] * n
        if dfs(u, visited, -1):
            return True

    return False

