def solve(n, edges):
    """Return True if a cycle exists in an undirected graph, False otherwise."""

    up = {}
    down = {}
    visited = []

    def bridge(u):
        if u in up:
            return up[u]
        return False

    for pair in edges:
        if pair[0] not in up:
            up[pair[0]] = -(len(edges))
            down[pair[0]] = len(edges)

        if pair[1] not in up:
            up[pair[1]] = -(len(edges))
            down[pair[1]] = len(edges)

        up[pair[0]] -= 1
        down[pair[1]] += 1
        if up[pair[1]] > len(edges):
            return True

    for i in range(n):
        temp = bridge(i)
        if temp is True:
            return True
        if down[i] > 0:
            continue
        visited.append(i)
        for j in range(i, n):
            if down[j] < 0:
                continue
            if j not in visited:
                return False

        visited.pop()

    return True
